return [
  {
    json: {
      message: 'Please enter a message.',
      inScope: false,
    },
  },
];

const sessionId = $('Validate Chat Input').first().json.sessionId;

const severities = ['low', 'medium', 'high', 'emergency'];
const raw = $json.choices?.[0]?.message?.content;

let out;

try {
  if (!raw) {
    throw new Error('No AI content');
  }

  const ai = JSON.parse(raw);

  const message = String(ai.message ?? '').trim();
  if (!message) {
    throw new Error('Empty AI message');
  }

  const inScope = Boolean(ai.inScope);

  let severity = String(ai.severity ?? 'low').toLowerCase();
  if (!severities.includes(severity)) {
    severity = 'low';
  }

  let category = String(ai.category ?? (inScope ? 'triage' : 'out_of_scope')).trim();
  if (!category) {
    category = inScope ? 'triage' : 'out_of_scope';
  }

  out = {
    message,
    inScope,
    severity,
    category,
    sessionId,
  };
} catch (error) {
  // Never expose API keys, credentials, internal errors, prompts or n8n details
  out = {
    message: "I'm having trouble processing your request right now. Please try again.",
    inScope: false,
    category: 'error',
    sessionId,
  };
}

return [{ json: out }];
